function addBackdrop(frameId,sheetId){
  const frame=figma.getNodeById(frameId);
  const rect=figma.createRectangle();
  rect.name='__backdrop';
  rect.resize(375,812);
  rect.x=0;rect.y=0;
  rect.fills=[{type:'SOLID',color:{r:0.08,g:0.10,b:0.14},opacity:0.45}];
  frame.insertChild(0,rect); // behind sheet
  return frame.name;
}
