r.push(addBackdrop('11:247','11:248'));
return r;

async function run(){
await figma.loadFontAsync({family:'Nunito',style:'SemiBold'});
async function setLabel(id,label){
  const inst=figma.getNodeById(id);
  if(!inst||inst.type!=='INSTANCE')return id+' not-instance';
  // access the source text child
  const t=inst.findOne(n=>n.type==='TEXT');
  if(t){await figma.loadFontAsync(t.fontName).catch(()=>{});}
  try{t.characters=label;if(t.fontName.style!=='SemiBold'){t.fontName={family:'Nunito',style:'SemiBold'};}}catch(e){return id+':'+label+' ERR '+e.message;}
  return id+':'+label+' OK('+(t?t.characters:'null')+')';
}
const r=[];
r.push(await setLabel('8:50','Let\x27s Continue'));
r.push(await setLabel('8:70','Start Ordering'));
r.push(await setLabel('11:134','Add to basket'));
r.push(await setLabel('11:174','Checkout'));
r.push(await setLabel('11:243','Pay with card'));
r.push(await setLabel('11:270','Complete Order'));
r.push(await setLabel('11:277','Track order'));
return r;}
return run();

